  switch (name) {
    case 'add':
      return addValue(doc, path, deepCopy(value));
    case 'remove':
      removeValue(doc, path, 'path not found');
      return doc;
    case 'replace':
      return replaceValue(doc, path, deepCopy(value));
    case 'move': {
